import sys
from io import StringIO
import unittest


def resolve():
    n = int(input())

    # 1文字ずつチェックするのでSET。
    s = list(input())

    # 全パターンの数(RGB1つずつ選択する場合)
    ans = s.count("R")*s.count("G")*s.count("B")

    # ここから条件(j-i≠k-j)を満たさないパターンを減算。
    s_len = len(s)
    minus = 0

    # i<=距離A=>j<=距離A=>k という状態で、距離Aが等しいパターンを列挙していく。
    for i in range(s_len-2):
        first = s[i]
        for j in range(1, 9999):

            # 文字数を超えるパターンは検証しない
            if i+j+j > s_len - 1:
                break

            # 1文字目,2文字目,3文字目が全部別の場合、除外するパターンである。(合計数から減算する)
            if first is not s[i+j] and first is not s[i+j+j] and s[i+j] is not s[i+j+j]:
                minus += 1

    print(ans - minus)




